CAT = "iepsaReports"; SEG = "REP"
# QQI 4N20604 learning outcomes 1.7 (court proceedings and witness procedures), 1.10 (documentation),
# 1.11 and 1.15 (preserving the scene), 1.12 and 1.16 (incident recording and reporting).
Q = [
('Why do guards use a bound notebook with numbered pages?',
 'Shows no pages are missing', ['It is cheaper to buy', 'It fits in a pocket', 'The law sets its colour'],
 'Numbered pages in a bound book show that nothing has been removed or added later, which makes the notes more reliable as evidence.'),
("What should a guard do when he makes a mistake in his notebook?",
 "Single line, then initial", ["Tear out the page", "Use correction fluid", "Scribble it out fully"],
 "A single line keeps the original words readable and the initials show who changed it. Torn pages or blanked-out words suggest tampering."),
('In a report, how should a guard refer to someone whose name he does not know?',
 'By a clear description', ["As 'the scumbag'", 'By a made-up name', 'He leaves them out'],
 "Describe the person (sex, approximate age, height, clothing) and call them, for example, 'the man in the green jacket'. Insults make a report look biased."),
("A guard's report says an assault happened 'at about ten'. Why is this weak?",
 'The time is not exact', ["It should say 'at night'", 'Reports never give times', 'It needs the date first'],
 "Reports should give exact times using the 24-hour clock, for example 22:04. 'About ten' could mean morning or night and invites challenge in court."),
("How should a guard record a time in a report to avoid any doubt?",
 "The 24-hour clock", ["Morning or evening", "Roughly, to the hour", "Before or after lunch"],
 "The 24-hour clock (for example 22:40) removes any doubt between morning and evening times."),
("Which description of a suspect is most useful?",
 "Head to toe, then clothes", ["He looked dodgy to me", "Normal height and build", "A man, I think"],
 "Working from head to toe (sex, age, height, build, hair, face, marks) and then clothing and footwear gives the Gardaí something they can actually use."),
("Why should a guard note a vehicle's registration and direction of travel after a theft?",
 "Helps the Gardaí trace it", ["For the insurer only", "To issue a parking fine", "To check the tax disc"],
 "A registration, make, colour and the direction the vehicle went let the Gardaí find it quickly."),
("A guard arrives first at the scene of a break-in. What is his main job regarding evidence?",
 "Preserve the scene", ["Tidy up the mess", "Collect what he can", "Let staff look around"],
 "Preserving the scene means keeping people out and touching nothing, so the Gardaí can gather evidence such as fingerprints, footprints and DNA."),
("How should a guard keep people out of a crime scene until the Gardaí arrive?",
 "Cordon it, control entry", ["Lock himself inside it", "Stand in the middle of it", "Let staff walk round it"],
 "A cordon, using tape or barriers and a single controlled entry point, keeps people out. Log anyone who must enter, such as paramedics."),
('The Gardaí arrive at a scene the guard has protected. What should he hand over?',
 'His notes and the scene log', ["The suspect's wallet", "The site's master key", 'His PSA identity card'],
 'The guard briefs the Gardaí and passes on his notes and the scene log so they know what happened and who has been in the scene. He then follows their directions.'),
("What is a scene log?",
 "Who enters and leaves", ["A list of stolen items", "A rota for guards", "The CCTV backup copy"],
 "A scene log records everyone who enters or leaves a cordoned scene, with times and reasons, protecting the chain of evidence."),
("A guard picks up a dropped knife at a scene because it is in the way. What has he risked?",
 "Contaminating the evidence", ["Breaking site rules on knives", "Nothing, it is helpful", "A fine from the PSA"],
 "Handling an item can destroy fingerprints or DNA and add the guard's own. Leave items where they are unless there is an immediate danger, and note anything you move."),
('A guard hands a copy of CCTV footage to a Garda. What should he record?',
 'Who got it and when', ["The Garda's home address", "The film's running time only", 'Nothing, the Garda has it'],
 'Recording who received the item, and when, keeps the chain of custody unbroken so the footage can be relied on in court.'),
("Why should CCTV footage of an incident be saved and handed over through the agreed procedure?",
 "To keep it usable as evidence", ["To post it on social media", "To show it to colleagues", "To delete it from the system faster"],
 "Saving the footage before it is overwritten and handing it over under the procedure, with a record, keeps it usable as evidence and complies with data protection rules."),
("Which document should a guard fill in when an employee slips on a wet floor?",
 "An accident report", ["A key register", "A visitor pass", "A patrol schedule"],
 "Accidents and injuries are recorded on the site's accident or incident report form, with the facts, any first aid given and witnesses."),
("Which court in Ireland hears most minor criminal cases a guard might give evidence in?",
 "The District Court", ["The Supreme Court", "The Court of Appeal", "The Special Criminal Court"],
 "The District Court deals with summary offences, tried by a judge without a jury, and public order offences are always dealt with there. Indictable offences such as murder and rape are sent forward to a higher court."),
("Before giving evidence as a witness in court, what will a guard be asked to do?",
 "Take an oath or affirm", ["Show his PSA badge", "Pay a court fee", "Sign the charge sheet"],
 "A witness swears an oath or makes an affirmation to tell the truth before giving evidence."),
("A guard witnessed a killing on site. Can the District Court try the murder charge?",
 "No, it goes to a higher court", ["Yes, every case ends there", "Only if he pleads guilty", "Only if the guard agrees"],
 "Murder and rape can never be dealt with in the District Court. These cases start there but are sent forward to a higher court for trial, where the guard would give evidence."),
("How should a guard answer questions in cross-examination?",
 "Truthfully, just what is asked", ["Argue with the barrister", "Add his own view of the accused", "Fill gaps with guesses"],
 "Answer the question asked, clearly and truthfully, and say so if you do not know or remember. Arguing or guessing harms your credibility."),
("A witness says taking an oath is against his religious belief. What may he do instead?",
 "Make a solemn affirmation", ["Refuse to give evidence", "Send a written note", "Swear on his PSA licence"],
 "Under section 1 of the Oaths Act 1888, a person who objects to an oath because he has no religious belief, or because an oath is contrary to it, may affirm instead, with the same force and effect."),
("What is an occurrence book or daily log used for?",
 "Recording each shift's events", ["Planning staff holidays", "Listing staff salaries", "Storing spare keys"],
 "The daily log records every event, check, call and handover on the shift in time order, giving the client and the next guard a full picture."),
("Why must a guard never back-date or change an entry in the daily log later?",
 "It ruins it as evidence", ["It wastes ink", "The client cannot read it", "It breaks copyright law"],
 "A log is only trusted if entries are made at the time and in order. Later changes, even well meant, make the whole record doubtful."),
("A witness to a fight wants to leave before the Gardaí arrive. What should the guard do?",
 "Ask for contact details", ["Detain the witness", "Take their phone", "Let them go without a word"],
 "Witnesses are not suspects and cannot be held. Ask for name and contact details so the Gardaí can follow up."),
("Instead of writing 'the man was aggressive', what makes a stronger report?",
 "Describe what he did and said", ["Underline the word aggressive", "Call him a thug instead", "Leave the behaviour out"],
 "Describing actions and words (he clenched his fists, shouted at the cashier, threw a chair) gives facts; a label like 'aggressive' is an opinion that can be challenged."),
]
